const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const { Client, GatewayIntentBits, ChannelType } = require('discord.js');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static('public'));

let discordClient = null;

io.on('connection', (socket) => {
    console.log('A user connected to the web UI');

    socket.on('login-bot', (token) => {
        if (discordClient) {
            discordClient.destroy();
        }

        discordClient = new Client({
            intents: [
                GatewayIntentBits.Guilds,
                GatewayIntentBits.GuildMessages,
                GatewayIntentBits.MessageContent
            ]
        });

        discordClient.on('ready', () => {
            console.log(`Logged in as ${discordClient.user.tag}!`);
            socket.emit('bot-ready', discordClient.user.tag);

            // Send guild list to frontend
            const guilds = discordClient.guilds.cache.map(guild => ({
                id: guild.id,
                name: guild.name
            }));
            socket.emit('guilds-list', guilds);
        });

        socket.on('get-channels', (guildId) => {
            const guild = discordClient.guilds.cache.get(guildId);
            if (!guild) return;

            const channels = guild.channels.cache
                .filter(c => c.type === ChannelType.GuildText)
                .map(c => ({
                    id: c.id,
                    name: c.name
                }));
            socket.emit('channels-list', channels);
        });

        socket.on('get-messages', async (channelId) => {
            try {
                const channel = await discordClient.channels.fetch(channelId);
                if (!channel || channel.type !== ChannelType.GuildText) return;

                const messages = await channel.messages.fetch({ limit: 50 });
                const messageList = messages.map(m => ({
                    author: m.author.tag,
                    content: m.content
                }));
                socket.emit('message-history', messageList);
            } catch (err) {
                console.error('Error fetching messages:', err);
            }
        });

        socket.on('send-message', async (data) => {
            try {
                const channel = await discordClient.channels.fetch(data.channelId);
                if (channel && channel.type === ChannelType.GuildText) {
                    await channel.send(data.content);
                }
            } catch (err) {
                console.error('Error sending message:', err);
            }
        });

        discordClient.on('messageCreate', (message) => {
            if (message.author.bot && message.author.id === discordClient.user.id) return;
            
            socket.emit('new-message', {
                channelId: message.channel.id,
                author: message.author.tag,
                content: message.content
            });
        });

        discordClient.login(token).catch((err) => {
            socket.emit('login-error', err.message);
        });
    });
});

server.listen(3000, () => {
    console.log('Server running at http://localhost:3000');
});
